using UnityEngine;

/// <summary>
/// Left-click swing for the wrench multitool. Tap = light swing; hold to charge and
/// release for a heavier swing (longer cooldown). The swing faces the mouse aim point.
/// When aimed at a ResourceNode the wrench "transforms" to that tool's attack animation,
/// otherwise it plays the plain wrench swing. Disabled while the wrench is airborne
/// (thrown). Exposes IsCharging / ChargeNormalized for the aim reticle.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    private IPlayerVisual _animDriver;

    [Tooltip("Delay from swing release to the hit landing (seconds). Tune for impact feel.")]
    [SerializeField] private float _hitDelay = 0.1f;

    private PlayerMouseAimer _aimer;
    private float _cooldown;
    private float _chargeTimer;
    private bool _charging;

    // Damage lands a short, tunable delay after release (impact timing), not instantly.
    private ResourceNode _pendingNode;
    private int _pendingDamage;
    private float _hitTimer;
    private bool _hitPending;

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.swingChargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.swingChargeTime)
        : 0f;

    private void Awake()
    {
        _aimer     = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
    }

    private void Update()
    {
        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        // Apply a queued hit once its delay elapses.
        if (_hitPending)
        {
            _hitTimer -= Time.deltaTime;
            if (_hitTimer <= 0f) ApplyPendingHit();
        }

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable)
        {
            // Wrench put away (or thrown) mid-charge: abort the frozen windup pose.
            if (_charging)
            {
                if (_animDriver != null) _animDriver.CancelSwing();
                _charging = false;
                _chargeTimer = 0f;
            }
            return;
        }

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
        {
            _charging = true;
            _chargeTimer = 0f;
            FaceAim();
            // Freeze the would-be tool on its windup frame; live-swapped while held.
            if (_animDriver != null) _animDriver.BeginChargePose(_aimer.SwingAnimIndex);
        }
        else if (_charging && Input.GetMouseButton(0))
        {
            _chargeTimer += Time.deltaTime;
            FaceAim();
            if (_animDriver != null) _animDriver.UpdateChargePose(_aimer.SwingAnimIndex, ChargeNormalized);
        }
        else if (_charging && Input.GetMouseButtonUp(0))
        {
            DoSwing();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void FaceAim()
    {
        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);
    }

    private void DoSwing()
    {
        if (_animDriver == null) return;

        FaceAim();

        // Tool comes from the surface under the cursor within melee reach (4 = wrench/air).
        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float charge = ChargeNormalized;
        bool heavy = charge >= (_config != null ? _config.heavySwingThreshold : 0.6f);

        // More charge → faster follow-through (the stored power releasing).
        float lightSpd = _config != null ? _config.lightSwingAnimSpeed : 1.0f;
        float heavySpd = _config != null ? _config.heavySwingAnimSpeed : 2.5f;
        _animDriver.ReleaseSwing(animIndex, Mathf.Lerp(lightSpd, heavySpd, charge));

        _cooldown = heavy
            ? (_config != null ? _config.heavySwingCooldown : 0.8f)
            : (_config != null ? _config.lightSwingCooldown : 0.45f);

        // Harvest damage only lands on ResourceNodes; non-resource surfaces just play the anim.
        // Capture the target + damage now, apply after a short tunable delay (impact feel).
        ResourceNode node = _aimer.MeleeResource;
        if (node != null)
        {
            _pendingNode = node;
            _pendingDamage = heavy
                ? (_config != null ? _config.heavySwingDamage : 2)
                : (_config != null ? _config.lightSwingDamage : 1);
            _hitTimer = _hitDelay;
            _hitPending = true;
        }
    }

    private void ApplyPendingHit()
    {
        _hitPending = false;
        if (_pendingNode != null && _pendingDamage > 0)
            _pendingNode.ReceiveHit(_pendingDamage);
        _pendingNode = null;
        _pendingDamage = 0;
    }
}

using UnityEngine;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }
}

using UnityEngine;

/// <summary>
/// The visual/animation surface the player's combat &amp; interaction controllers drive,
/// decoupled from how the body is actually rendered. Implemented by both the legacy
/// sprite-sheet driver (<see cref="FlynnAnimationDriver"/>) and the procedural cube-rig
/// driver (<see cref="ProceduralCharacterDriver"/>) so the same wrench/throw/rope/reticle
/// logic works against either body without edits.
///
/// Controllers resolve it via <c>GetComponent&lt;IPlayerVisual&gt;()</c> in Awake.
/// </summary>
public interface IPlayerVisual
{
    /// <summary>World-space "hand" / chest origin for thrown projectiles and the rope end.</summary>
    Vector3 VisualCenter { get; }

    /// <summary>VisualCenter projected to the character's foot Y (ground-plane indicators).</summary>
    Vector3 VisualGroundCenter { get; }

    /// <summary>True while an attack/swing is playing (gates re-triggering).</summary>
    bool IsAttacking { get; }

    /// <summary>Fire the attack pose for the given tool index (1=pick 2=axe 3=hammer 4=wrench).</summary>
    void TriggerAttack(int animIndex);

    /// <summary>Enter the windup hold for the given tool index.</summary>
    void BeginChargePose(int animIndex);

    /// <summary>Scrub the windup pose with charge fraction 0→1 (also live-swaps the tool).</summary>
    void UpdateChargePose(int animIndex, float charge01);

    /// <summary>Release the swing at the given playback speed (higher = faster follow-through).</summary>
    void ReleaseSwing(int animIndex, float animSpeed);

    /// <summary>Abort a windup and return to neutral.</summary>
    void CancelSwing();

    /// <summary>Orient the body toward a world-space XZ direction. Ignores Y; no-op on zero.</summary>
    void FaceWorldDirection(Vector3 worldDir);
}

