    public static void Setup()
    {
        // 1. Find attack_04 sprites sorted by frame number
        var folder = "Assets/Flynn/Sprites/character_animations/attack_04";
        var guids = AssetDatabase.FindAssets("t:Sprite", new[] { folder });
        var paths = guids
            .Select(AssetDatabase.GUIDToAssetPath)
            .OrderBy(p => ExtractFrameNumber(p))
            .ToArray();

        if (paths.Length == 0)
        {
            Debug.LogError($"No sprites found in {folder}");
            return;
        }

        var sprites = paths.Select(p => AssetDatabase.LoadAssetAtPath<Sprite>(p)).ToArray();
        Debug.Log($"Found {sprites.Length} sprites for wrench attack");

        // 2. Create the animation clip
        var clip = new AnimationClip();
        clip.name = "Flynn_attack_04";
        clip.frameRate = 12f;

        var keyframes = new ObjectReferenceKeyframe[sprites.Length];
        for (int i = 0; i < sprites.Length; i++)
        {
            keyframes[i] = new ObjectReferenceKeyframe
            {
                time = i / 12f,
                value = sprites[i]
            };
        }

        var binding = new EditorCurveBinding
        {
            type = typeof(SpriteRenderer),
            path = "",
            propertyName = "m_Sprite"
        };

        AnimationUtility.SetObjectReferenceCurve(clip, binding, keyframes);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = false;
        AnimationUtility.SetAnimationClipSettings(clip, settings);

        // 3. Save the clip
        var saveDir = "Assets/Flynn/Animations";
        if (!Directory.Exists(saveDir)) Directory.CreateDirectory(saveDir);
        var savePath = $"{saveDir}/Flynn_attack_04.anim";

        AssetDatabase.CreateAsset(clip, savePath);
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log($"Created wrench attack clip at {savePath} ({sprites.Length} frames, {clip.length:F2}s)");

        // 4. Load the animator controller
        var controllerPath = "Assets/Flynn/Animations/Flynn_AnimatorController.controller";
        var controller = AssetDatabase.LoadAssetAtPath<AnimatorController>(controllerPath);
        if (controller == null)
        {
            Debug.LogError($"Animator controller not found at {controllerPath}");
            return;
        }

        var rootStateMachine = controller.layers[0].stateMachine;

        // Check if Attack_Wrench already exists
        var existingState = rootStateMachine.states
            .Select(s => s.state)
            .FirstOrDefault(s => s.name == "Attack_Wrench");

        if (existingState != null)
        {
            Debug.Log("Attack_Wrench state already exists — updating motion");
            existingState.motion = clip;
        }
        else
        {
            // 5. Add Attack_Wrench state
            var attackState = rootStateMachine.AddState("Attack_Wrench", new Vector3(300, 200, 0));
            attackState.motion = clip;
            attackState.tag = "Attack";

            // 6. AnyState → Attack_Wrench transition
            var anyTransition = rootStateMachine.AddAnyStateTransition(attackState);
            anyTransition.AddCondition(AnimatorConditionMode.If, 0, "Attack");
            anyTransition.AddCondition(AnimatorConditionMode.Equals, 4, "AttackIndex");
            anyTransition.duration = 0f;
            anyTransition.canTransitionToSelf = false;
            anyTransition.hasExitTime = false;
            anyTransition.hasFixedDuration = true;

            // 7. Attack_Wrench → default state (blend tree / locomotion)
            var exitTransition = attackState.AddTransition(rootStateMachine.defaultState);
            exitTransition.hasExitTime = true;
            exitTransition.exitTime = 0.9f;
            exitTransition.duration = 0.1f;
            exitTransition.hasFixedDuration = true;

            Debug.Log("Added Attack_Wrench state with AnyState transition and exit transition");
        }

        EditorUtility.SetDirty(controller);
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        Debug.Log("Wrench attack animation setup complete!");
    }

    static int ExtractFrameNumber(string path)
    {
        var match = Regex.Match(Path.GetFileNameWithoutExtension(path), @"(\d+)$");
        return match.Success ? int.Parse(match.Groups[1].Value) : 0;
    }
}

