using UnityEngine;
using UnityEditor;

// Wire the WrenchSwingArc reference on the WrenchSwingController
var go = GameObject.Find("Player_Proc");
if (go == null) { Debug.LogError("Player_Proc not found"); return; }

var swing = go.GetComponent<WrenchSwingController>();
var arc = go.GetComponent<WrenchSwingArc>();
if (swing == null || arc == null) { Debug.LogError($"swing={swing} arc={arc}"); return; }

// Use SerializedObject to set the _swingArc field
var so = new SerializedObject(swing);
var prop = so.FindProperty("_swingArc");
if (prop == null) { Debug.LogError("_swingArc property not found"); return; }
prop.objectReferenceValue = arc;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(go);
Debug.Log($"Wired WrenchSwingArc → WrenchSwingController._swingArc on {go.name}");

using UnityEngine;
using UnityEditor;

// Find Player_Proc including inactive objects
var allTransforms = Resources.FindObjectsOfTypeAll<Transform>();
Transform playerProc = null;
foreach (var t in allTransforms)
{
    if (t.name == "Player_Proc" && t.gameObject.scene.isLoaded)
    {
        playerProc = t;
        break;
    }
}

if (playerProc == null) { Debug.LogError("Player_Proc still not found"); return; }

var go = playerProc.gameObject;
var swing = go.GetComponent<WrenchSwingController>();
var arc = go.GetComponent<WrenchSwingArc>();
if (swing == null || arc == null) { Debug.LogError($"swing={swing} arc={arc}"); return; }

var so = new SerializedObject(swing);
var prop = so.FindProperty("_swingArc");
if (prop == null) { Debug.LogError("_swingArc property not found"); return; }
prop.objectReferenceValue = arc;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(go);
Debug.Log($"Wired WrenchSwingArc → WrenchSwingController._swingArc on {go.name}");

