using UnityEngine;

/// <summary>
/// Code-driven directional swipe arc for the wrench. On <see cref="Play"/> a procedural
/// arc mesh sweeps from one side to the other in front of the player, oriented toward the
/// supplied world direction (player → mouse). No Animator needed — the sweep, colour, and
/// fade are driven entirely from Update.
///
/// Hook-up: WrenchSwingController.DoSwing calls <see cref="Play"/> with the aim direction.
/// The arc lives as a child on the player root so it inherits position automatically.
/// </summary>
[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class WrenchSwingArc : MonoBehaviour
{
    [Header("Arc shape")]
    [Tooltip("Radius of the arc (match melee range).")]
    [SerializeField] private float _radius = 1.8f;
    [Tooltip("Total sweep angle in degrees (e.g. 120 = 60° each side of centre).")]
    [SerializeField] private float _sweepAngle = 120f;
    [Tooltip("Inner cut-out radius so the arc is a wedge ring, not a solid pie.")]
    [SerializeField] private float _innerRadius = 0.3f;
    [Tooltip("Height of the arc above the player's feet.")]
    [SerializeField] private float _arcHeight = 0.5f;
    [Tooltip("Thickness of the arc band (outer ring width).")]
    [SerializeField] private float _bandWidth = 0.35f;

    [Header("Timing")]
    [Tooltip("How long the sweep takes (seconds).")]
    [SerializeField] private float _sweepDuration = 0.25f;
    [Tooltip("Additional fade-out time after the sweep completes.")]
    [SerializeField] private float _fadeOutDuration = 0.15f;

    [Header("Appearance")]
    [SerializeField] private Color _arcColor = new Color(1f, 0.95f, 0.7f, 0.7f);

    private MeshFilter _mf;
    private MeshRenderer _mr;
    private Material _mat;

    // Sweep state
    private bool _playing;
    private float _timer;
    private float _facingAngle;   // Y-rotation that points the arc centre toward the aim dir
    private float _sweepStart;    // angle offset at sweep start
    private float _sweepEnd;      // angle offset at sweep end

    private static readonly int ColorProp = Shader.PropertyToID("_Color");

    private void Awake()
    {
        _mf = GetComponent<MeshFilter>();
        _mr = GetComponent<MeshRenderer>();

        // Simple unlit transparent material
        _mat = new Material(Shader.Find("Unlit/Transparent"));
        _mat.color = _arcColor;
        _mr.material = _mat;
        _mr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
        _mr.receiveShadows = false;

        // Build the full arc mesh (will be masked by sweep progress)
        RebuildMesh();

        _mr.enabled = false;
    }

    /// <summary>
    /// Trigger the swipe arc facing the given world XZ direction.
    /// Call from WrenchSwingController.DoSwing with player→mouse direction.
    /// </summary>
    public void Play(Vector3 worldDirection)
    {
        Vector3 flat = Vector3.ProjectOnPlane(worldDirection, Vector3.up);
        if (flat.sqrMagnitude < 0.001f) flat = Vector3.forward;
        _facingAngle = Mathf.Atan2(flat.x, flat.z) * Mathf.Rad2Deg;

        // Sweep from the left side to the right side (right-hand swing)
        float halfSweep = _sweepAngle / 2f;
        _sweepStart = -halfSweep;
        _sweepEnd = halfSweep;

        _timer = 0f;
        _playing = true;
        _mr.enabled = true;
        UpdateVisual(0f);
    }

    private void Update()
    {
        if (!_playing) return;

        _timer += Time.deltaTime;
        float totalDuration = _sweepDuration + _fadeOutDuration;

        if (_timer >= totalDuration)
        {
            _playing = false;
            _mr.enabled = false;
            return;
        }

        float t = Mathf.Clamp01(_timer / _sweepDuration);

        // Alpha: full during sweep, fading out after
        float alpha;
        if (_timer <= _sweepDuration)
            alpha = _arcColor.a;
        else
            alpha = _arcColor.a * (1f - (_timer - _sweepDuration) / _fadeOutDuration);

        UpdateVisual(t, alpha);
    }

    private void UpdateVisual(float t01, float? alphaOverride = null)
    {
        // Rotate the whole object to face the aim direction
        transform.localRotation = Quaternion.Euler(0f, _facingAngle, 0f);
        transform.localPosition = Vector3.up * _arcHeight;

        // Rebuild the arc mesh up to the current sweep progress
        float currentEndAngle = Mathf.Lerp(_sweepStart, _sweepEnd, t01);
        BuildArcMesh(_sweepStart, currentEndAngle);

        // Apply colour with alpha
        Color c = _arcColor;
        if (alphaOverride.HasValue) c.a = alphaOverride.Value;
        _mat.color = c;
    }

    /// <summary>Rebuild the full arc mesh (used in Awake for initial setup).</summary>
    private void RebuildMesh() => BuildArcMesh(_sweepStart, _sweepEnd);

    /// <summary>Build a flat arc mesh from startAngle to endAngle (degrees, relative to forward).</summary>
    private void BuildArcMesh(float startAngle, float endAngle)
    {
        if (_mf == null) return;

        int segments = Mathf.Max(2, Mathf.RoundToInt(Mathf.Abs(endAngle - startAngle) / 5f));
        float outerR = _radius;
        float innerR = _radius - _bandWidth;
        if (innerR < _innerRadius) innerR = _innerRadius;

        // 2 verts per segment (inner + outer) + 2 for the end caps
        int vertCount = (segments + 1) * 2;
        int triCount = segments * 2; // 2 tris per segment

        var verts = new Vector3[vertCount];
        var tris = new int[triCount * 3];
        var uvs = new Vector2[vertCount];

        for (int i = 0; i <= segments; i++)
        {
            float frac = (float)i / segments;
            float angleDeg = Mathf.Lerp(startAngle, endAngle, frac);
            float angleRad = angleDeg * Mathf.Deg2Rad;
            float cos = Mathf.Cos(angleRad);
            float sin = Mathf.Sin(angleRad);

            // Outer vertex
            verts[i * 2] = new Vector3(sin * outerR, 0f, cos * outerR);
            // Inner vertex
            verts[i * 2 + 1] = new Vector3(sin * innerR, 0f, cos * innerR);

            uvs[i * 2] = new Vector2(frac, 1f);
            uvs[i * 2 + 1] = new Vector2(frac, 0f);
        }

        for (int i = 0; i < segments; i++)
        {
            int o1 = i * 2;
            int o2 = (i + 1) * 2;
            int idx = i * 6;

            // Triangle 1: outer-i, inner-i, outer-i+1
            tris[idx + 0] = o1;
            tris[idx + 1] = o1 + 1;
            tris[idx + 2] = o2;
            // Triangle 2: outer-i+1, inner-i, inner-i+1
            tris[idx + 3] = o2;
            tris[idx + 4] = o1 + 1;
            tris[idx + 5] = o2 + 1;
        }

        var mesh = new Mesh();
        mesh.vertices = verts;
        mesh.triangles = tris;
        mesh.uv = uvs;
        mesh.RecalculateNormals();

        _mf.sharedMesh = mesh;
    }
}

