using UnityEngine;

/// <summary>
/// Simple directional swipe arc for the wrench. Pops up facing player→mouse,
/// sweeps across, then fades. Code-only, no Animator. 2.5D — flat on XZ.
/// </summary>
[RequireComponent(typeof(LineRenderer))]
public class WrenchSwingArc : MonoBehaviour
{
    [SerializeField] private float _radius = 1.8f;
    [SerializeField] private float _sweepAngle = 120f;
    [SerializeField] private float _duration = 0.3f;
    [SerializeField] private float _fadeOut = 0.12f;
    [SerializeField] private float _arcHeight = 0.3f;

    private LineRenderer _lr;
    private bool _playing;
    private float _timer;
    private float _facingAngle;

    private void Awake()
    {
        _lr = GetComponent<LineRenderer>();
        _lr.useWorldSpace = false;
        _lr.startWidth = 0.08f;
        _lr.endWidth = 0.04f;
        _lr.positionCount = 0;
        _lr.enabled = false;
    }

    public void Play(Vector3 worldDirection)
    {
        Vector3 flat = Vector3.ProjectOnPlane(worldDirection, Vector3.up);
        if (flat.sqrMagnitude < 0.001f) flat = Vector3.forward;
        _facingAngle = Mathf.Atan2(flat.x, flat.z) * Mathf.Rad2Deg;

        _timer = 0f;
        _playing = true;
        _lr.enabled = true;
    }

    private void Update()
    {
        if (!_playing) return;

        _timer += Time.deltaTime;
        float total = _duration + _fadeOut;

        if (_timer >= total)
        {
            _playing = false;
            _lr.enabled = false;
            return;
        }

        // Sweep progress 0→1 during active phase
        float t = Mathf.Clamp01(_timer / _duration);

        // Rotate to face the aim direction
        transform.localRotation = Quaternion.Euler(0f, _facingAngle, 0f);
        transform.localPosition = Vector3.up * _arcHeight;

        // Build arc line from -halfAngle to +halfAngle * t (sweeping open)
        float half = _sweepAngle / 2f;
        float currentEnd = Mathf.Lerp(-half, half, t);

        int segments = 16;
        _lr.positionCount = segments + 1;
        for (int i = 0; i <= segments; i++)
        {
            float angle = Mathf.Lerp(-half, currentEnd, (float)i / segments) * Mathf.Deg2Rad;
            _lr.SetPosition(i, new Vector3(Mathf.Sin(angle) * _radius, 0f, Mathf.Cos(angle) * _radius));
        }

        // Fade out after sweep
        float alpha = _timer <= _duration ? 1f : 1f - (_timer - _duration) / _fadeOut;
        _lr.startColor = new Color(1f, 0.9f, 0.6f, alpha);
        _lr.endColor = new Color(1f, 0.9f, 0.6f, alpha * 0.5f);
    }
}

