args.script:
using UnityEngine;
using UnityEditor;

var go = GameObject.Find("Player");
if (go == null) { Debug.LogError("Player not found"); return; }

// Remove the leftover MeshFilter and MeshRenderer from the old version
var mf = go.GetComponent<MeshFilter>();
var mr = go.GetComponent<MeshRenderer>();
if (mf != null) { Undo.DestroyObjectImmediate(mf); Debug.Log("Removed MeshFilter"); }
if (mr != null) { Undo.DestroyObjectImmediate(mr); Debug.Log("Removed MeshRenderer"); }

// Re-wire the swing arc reference (component instance may have changed)
var swing = go.GetComponent<WrenchSwingController>();
var arc = go.GetComponent<WrenchSwingArc>();
if (swing != null && arc != null)
{
    var so = new SerializedObject(swing);
    so.FindProperty("_swingArc").objectReferenceValue = arc;
    so.ApplyModifiedProperties();
    Debug.Log("Re-wired _swingArc reference");
}

// Apply to prefab
PrefabUtility.ApplyPrefabInstance(go, InteractionMode.AutomatedAction);
Debug.Log("Applied to Player.prefab");

